('7112930d-527c-47dc-85f6-1f03a49d603c', 'lecture', 'lecture', 'en', 'vi', 'word', 'noun / verb', '/ˈlɛk.tʃər/', 'LEK-cher', '[{"text":"(n) bài giảng, buổi thuyết trình","language":"vi"},{"text":"(v) giảng bài, thuyết giảng; (informal) mắng mỏ, giảng đạo đức","language":"vi"}]'::jsonb, '[{"sentence":"The professor gave a lecture on marketing strategies.","translation":"Giáo sư đã có bài giảng về các chiến lược tiếp thị."},{"sentence":"She lectures at Harvard Business School.","translation":"Cô ấy giảng dạy tại Trường Kinh doanh Harvard."}]'::jsonb, ARRAY['academic', 'toeic-part5', 'education'], 'lecturer = người giảng bài; đừng nhầm với speaker (diễn giả)', 'bài giảng / giảng bài', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'across', 'across', 'en', 'vi', 'word', 'preposition / adverb', '/əˈkrɒs/', 'uh-KROS', '[{"text":"(prep) qua, ngang qua, trên khắp","language":"vi"},{"text":"(adv) sang phía bên kia","language":"vi"}]'::jsonb, '[{"sentence":"The new policy applies across all departments.","translation":"Chính sách mới được áp dụng trên toàn bộ các phòng ban."},{"sentence":"She walked across the street.","translation":"Cô ấy đi qua đường."}]'::jsonb, ARRAY['preposition', 'toeic-part5', 'direction'], NULL, 'qua / ngang qua / khắp', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'inside', 'inside + N (place)', 'en', 'vi', 'phrase', 'preposition / adverb / adjective', '/ɪnˈsaɪd/', 'in-SIDE', '[{"text":"(prep) bên trong + danh từ chỉ địa điểm","language":"vi"},{"text":"(adv) ở bên trong","language":"vi"},{"text":"(adj) nội bộ, bên trong","language":"vi"}]'::jsonb, '[{"sentence":"Please wait inside the building.","translation":"Vui lòng chờ bên trong tòa nhà."},{"sentence":"The meeting is held inside the conference room.","translation":"Cuộc họp được tổ chức bên trong phòng hội nghị."}]'::jsonb, ARRAY['preposition', 'location', 'toeic-part5'], 'Cấu trúc: inside + N chỉ nơi chốn', 'bên trong', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'among', 'among + Ns (plural noun)', 'en', 'vi', 'phrase', 'preposition', '/əˈmʌŋ/', 'uh-MUNG', '[{"text":"(prep) trong số, giữa (nhiều hơn 2 đối tượng)","language":"vi"}]'::jsonb, '[{"sentence":"Among the candidates, she was the most qualified.","translation":"Trong số các ứng viên, cô ấy có trình độ cao nhất."},{"sentence":"The bonus was divided among all employees.","translation":"Tiền thưởng được chia đều cho tất cả nhân viên."}]'::jsonb, ARRAY['preposition', 'toeic-part5'], 'among dùng cho ≥3 đối tượng; between dùng cho 2 đối tượng', 'trong số / giữa (nhiều người/vật)', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'take place', 'take place', 'en', 'vi', 'idiom', 'verb phrase', '/teɪk pleɪs/', 'tayk plays', '[{"text":"(v phrase) diễn ra, xảy ra (= occur, happen)","language":"vi"}]'::jsonb, '[{"sentence":"The annual conference will take place in Hanoi next month.","translation":"Hội nghị thường niên sẽ diễn ra tại Hà Nội vào tháng tới."},{"sentence":"The ceremony took place at the hotel.","translation":"Buổi lễ đã diễn ra tại khách sạn."}]'::jsonb, ARRAY['idiom', 'toeic-part7', 'events'], NULL, 'diễn ra / xảy ra', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'last', 'last', 'en', 'vi', 'word', 'verb / adjective / adverb / determiner', '/lɑːst/', 'lahst', '[{"text":"(v) kéo dài, tồn tại","language":"vi"},{"text":"(adj) cuối cùng, vừa rồi","language":"vi"},{"text":"(adv) lần cuối cùng","language":"vi"},{"text":"(det) cuối, trước đó","language":"vi"}]'::jsonb, '[{"sentence":"The meeting lasted two hours.","translation":"Cuộc họp kéo dài hai tiếng."},{"sentence":"The last item on the agenda is budget review.","translation":"Mục cuối cùng trong chương trình nghị sự là xem xét ngân sách."}]'::jsonb, ARRAY['toeic-part5', 'time', 'duration'], NULL, 'kéo dài / cuối cùng', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'antique shop', 'antique shop', 'en', 'vi', 'phrase', 'noun phrase', '/ænˈtiːk ʃɒp/', 'an-TEEK shop', '[{"text":"(n) cửa hàng đồ cổ","language":"vi"}]'::jsonb, '[{"sentence":"She found a beautiful vase at an antique shop downtown.","translation":"Cô ấy tìm thấy một chiếc bình đẹp tại cửa hàng đồ cổ ở trung tâm thành phố."}]'::jsonb, ARRAY['noun-phrase', 'shopping', 'toeic-part4'], NULL, 'cửa hàng đồ cổ', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'resident', 'resident', 'en', 'vi', 'word', 'noun / adjective', '/ˈrɛz.ɪ.dənt/', 'REZ-ih-dent', '[{"text":"(n) cư dân, người cư trú","language":"vi"},{"text":"(adj) thường trú, cư trú tại chỗ","language":"vi"}]'::jsonb, '[{"sentence":"All residents must register their vehicles.","translation":"Tất cả cư dân phải đăng ký xe của mình."},{"sentence":"She is a resident of Ho Chi Minh City.","translation":"Cô ấy là cư dân của Thành phố Hồ Chí Minh."}]'::jsonb, ARRAY['noun', 'community', 'toeic-part6'], NULL, 'cư dân / người cư trú', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'inhabitant', 'inhabitant', 'en', 'vi', 'word', 'noun', '/ɪnˈhæb.ɪ.tənt/', 'in-HAB-ih-tant', '[{"text":"(n) người sinh sống, cư dân (của một vùng/thành phố)","language":"vi"}]'::jsonb, '[{"sentence":"The city has over 9 million inhabitants.","translation":"Thành phố có hơn 9 triệu cư dân."}]'::jsonb, ARRAY['noun', 'community', 'formal'], 'inhabitant mang tính văn phong hơn resident; thường dùng cho số liệu thống kê', 'người sinh sống / cư dân', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'ongoing', 'ongoing', 'en', 'vi', 'word', 'adjective', '/ˈɒn.ɡəʊ.ɪŋ/', 'ON-goh-ing', '[{"text":"(adj) đang diễn ra, đang tiến hành (= current, in progress)","language":"vi"}]'::jsonb, '[{"sentence":"The ongoing negotiations are expected to conclude next week.","translation":"Các cuộc đàm phán đang diễn ra dự kiến sẽ kết thúc vào tuần tới."},{"sentence":"This is an ongoing project.","translation":"Đây là một dự án đang tiến hành."}]'::jsonb, ARRAY['adjective', 'toeic-part5', 'status'], 'Synonyms: current, in progress, continuing, active', 'đang diễn ra / hiện tại', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'as a result of', 'as a result of', 'en', 'vi', 'phrase', 'prepositional phrase (connector)', '/æz ə rɪˈzʌlt ɒv/', 'az uh rih-ZULT uv', '[{"text":"(phrase) do kết quả của, vì, bởi vì (= because of, due to, owing to)","language":"vi"}]'::jsonb, '[{"sentence":"As a result of the merger, 200 jobs were eliminated.","translation":"Do kết quả của vụ sáp nhập, 200 việc làm đã bị cắt giảm."},{"sentence":"Sales increased as a result of the new marketing campaign.","translation":"Doanh số tăng nhờ chiến dịch tiếp thị mới."}]'::jsonb, ARRAY['connector', 'cause-effect', 'toeic-part6'], 'as a result of + N/Ving vs as a result, + clause', 'do kết quả của / vì', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'media organization', 'media organization', 'en', 'vi', 'phrase', 'noun phrase', '/ˈmiː.di.ə ˌɔː.ɡən.aɪˈzeɪ.ʃən/', 'MEE-dee-uh or-guh-nih-ZAY-shun', '[{"text":"(n) tổ chức truyền thông","language":"vi"}]'::jsonb, '[{"sentence":"Several media organizations covered the press conference.","translation":"Một số tổ chức truyền thông đã đưa tin về cuộc họp báo."}]'::jsonb, ARRAY['noun-phrase', 'media', 'business'], NULL, 'tổ chức truyền thông', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'suspicious', 'suspicious', 'en', 'vi', 'word', 'adjective', '/səˈspɪʃ.əs/', 'suh-SPISH-us', '[{"text":"(adj) nghi ngờ, đáng ngờ (= doubtful, dubious)","language":"vi"}]'::jsonb, '[{"sentence":"The manager was suspicious of the sudden increase in expenses.","translation":"Người quản lý nghi ngờ về sự tăng đột biến chi phí."},{"sentence":"There was suspicious activity in the account.","translation":"Có hoạt động đáng ngờ trong tài khoản."}]'::jsonb, ARRAY['adjective', 'toeic-part7', 'tone'], NULL, 'nghi ngờ / đáng ngờ', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'computer virus', 'computer virus', 'en', 'vi', 'phrase', 'noun phrase', '/kəmˈpjuː.tər ˈvaɪ.rəs/', 'kum-PYOO-ter VY-rus', '[{"text":"(n) vi-rút máy tính","language":"vi"}]'::jsonb, '[{"sentence":"The IT department detected a computer virus in the system.","translation":"Bộ phận CNTT đã phát hiện vi-rút máy tính trong hệ thống."}]'::jsonb, ARRAY['noun-phrase', 'IT', 'technology'], NULL, 'vi-rút máy tính', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'break', 'break', 'en', 'vi', 'word', 'noun / verb', '/breɪk/', 'brayk', '[{"text":"(n) giờ nghỉ, khoảng nghỉ; sự gãy vỡ; cơ hội","language":"vi"},{"text":"(v) gãy, vỡ; phá vỡ; nghỉ giải lao","language":"vi"}]'::jsonb, '[{"sentence":"We''ll take a short break and resume at 3 p.m.","translation":"Chúng ta sẽ nghỉ giải lao ngắn và tiếp tục lúc 3 giờ chiều."},{"sentence":"The commercial break lasted 2 minutes.","translation":"Quảng cáo giải lao kéo dài 2 phút."}]'::jsonb, ARRAY['noun', 'verb', 'toeic-part4', 'workplace'], NULL, 'giờ nghỉ / gãy vỡ', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'spread', 'spread', 'en', 'vi', 'word', 'verb / noun', '/sprɛd/', 'spred', '[{"text":"(v) lan rộng, truyền bá, phổ biến; trải ra","language":"vi"},{"text":"(n) sự lan rộng; khoảng cách","language":"vi"}]'::jsonb, '[{"sentence":"The news spread quickly across the company.","translation":"Tin tức lan nhanh khắp công ty."},{"sentence":"They are working to spread awareness about the new policy.","translation":"Họ đang nỗ lực truyền bá nhận thức về chính sách mới."}]'::jsonb, ARRAY['verb', 'toeic-part5', 'communication'], NULL, 'lan rộng / truyền bá', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'balance', 'balance', 'en', 'vi', 'word', 'noun / verb', '/ˈbæl.əns/', 'BAL-uns', '[{"text":"(n) số dư (tài khoản), sự cân bằng, thăng bằng","language":"vi"},{"text":"(v) cân bằng, giữ thăng bằng","language":"vi"}]'::jsonb, '[{"sentence":"Please check your outstanding balance before the due date.","translation":"Vui lòng kiểm tra số dư còn lại trước ngày đáo hạn."},{"sentence":"The budget needs to be balanced by the end of the quarter.","translation":"Ngân sách cần được cân bằng trước cuối quý."}]'::jsonb, ARRAY['noun', 'verb', 'finance', 'toeic-part5'], NULL, 'số dư / cân bằng', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'surface transportation', 'surface transportation', 'en', 'vi', 'phrase', 'noun phrase', '/ˈsɜː.fɪs ˌtræns.pɔːˈteɪ.ʃən/', 'SUR-fis trans-por-TAY-shun', '[{"text":"(n) vận tải đường bộ / đường thủy (vận tải trên mặt đất, không phải hàng không)","language":"vi"}]'::jsonb, '[{"sentence":"Surface transportation includes trucks, trains, and ships.","translation":"Vận tải đường bộ bao gồm xe tải, tàu hỏa và tàu thủy."}]'::jsonb, ARRAY['noun-phrase', 'logistics', 'transportation'], NULL, 'vận tải đường bộ', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'hiring manager', 'hiring manager', 'en', 'vi', 'phrase', 'noun phrase', '/ˈhaɪərɪŋ ˈmænɪdʒər/', 'HY-ring MAN-ih-jer', '[{"text":"(n) người quản lý tuyển dụng, trưởng bộ phận tuyển dụng","language":"vi"}]'::jsonb, '[{"sentence":"Please send your resume directly to the hiring manager.","translation":"Vui lòng gửi CV trực tiếp đến người quản lý tuyển dụng."}]'::jsonb, ARRAY['noun-phrase', 'HR', 'recruitment', 'toeic-part6'], NULL, 'người quản lý tuyển dụng', 'new'),
('7112930d-527c-47dc-85f6-1f03a49d603c', 'qualification', 'qualification', 'en', 'vi', 'word', 'noun', '/ˌkwɒl.ɪ.fɪˈkeɪ.ʃən/', 'kwol-ih-fih-KAY-shun', '[{"text":"(n) bằng cấp, trình độ chuyên môn; điều kiện, tiêu chuẩn","language":"vi"}]'::jsonb, '[{"sentence":"She has all the qualifications required for this position.","translation":"Cô ấy có đủ tất cả bằng cấp cần thiết cho vị trí này."},{"sentence":"Applicants must submit their resume and qualifications.","translation":"Ứng viên phải nộp CV và bằng cấp của mình."}]'::jsonb, ARRAY['noun', 'HR', 'recruitment', 'toeic-part6'], NULL, 'bằng cấp / trình độ', 'new');
